const pageColors={inicio:'mint',tarefas:'blue',rotina:'amber',habitos:'mint',treino:'blue',dieta:'mint',financas:'mint',calendario:'blue',compras:'amber',zone:'violet',caverna:'amber',loja:'violet',metas:'mint',configuracoes:'blue'};
