function ensureExtra(){if(!state.extra)state.extra={};const defaults={meals:{},mealOpen:0,shopping:[],market:[],orders:[],goals:[],redeemed:[],cave:[],caveDays:[],measurements:[],workoutLog:[],exercises:{},events:[],wellbeing:[],savings:0,settings:{sounds:true,reminders:true,hover:true},quadrants:{},historySeeded:true,marketHistory:[]};for(const [key,value]of Object.entries(defaults))if(state.extra[key]===undefined)state.extra[key]=structuredClone(value);return state.extra;}
function tabset(group,items){return `<div class="section-tabs" role="group" aria-label="Abas ${group}">${items.map(([id,label])=>`<button data-action="view" data-group="${group}" data-view="${id}" aria-pressed="${views[group]===id}" class="${views[group]===id?'active':''}">${label}</button>`).join('')}</div>`;}
function newButton(label,kind,ico='plus'){return `<button class="button primary" data-action="newRecord" data-kind="${kind}">${icon(ico)}${label}</button>`;}
function blank(title,description,ico='layers',action=''){return `<div class="panel empty-state"><div class="empty-symbol">${icon(ico)}</div><h3>${title}</h3><p>${description}</p>${action}</div>`;}
function miniStat(label,value,sub,color=''){return `<div class="mini-stat ${color}"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`;}
function dailyLedger(){return Array.from({length:31},(_,i)=>{const day=i+1;const incoming=receipts.filter(r=>Number(r[3].split('/')[0])===day).reduce((s,r)=>s+r[1],0);const outgoing=expenses.filter(r=>Number(r[3].split('/')[0])===day).reduce((s,r)=>s+r[1],0);return {day,incoming,outgoing,net:incoming-outgoing};});}
function chart(values,{color='mint',label='Valores',unit='R$',labels=['01 out','08 out','15 out','22 out','31 out'],height=185}={}){const id='area-'+(++chartCounter),min=Math.min(0,...values),max=Math.max(1,...values),range=max-min||1;const pts=values.map((v,i)=>[14+i/(Math.max(1,values.length-1))*672,12+(max-v)/range*130]);const line=pts.map((p,i)=>(i?'L':'M')+p.map(v=>v.toFixed(2)).join(',')).join(' '),area=`${line} L686,150 L14,150 Z`;return `<div class="flow-chart ${color}"><svg viewBox="0 0 700 175" preserveAspectRatio="none" style="height:${height}px" role="img" aria-label="${esc(label)}"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="currentColor" stop-opacity=".22"/><stop offset="100%" stop-color="currentColor" stop-opacity="0"/></linearGradient></defs>${[20,62,104,146].map(y=>`<path class="chart-grid" d="M14 ${y}H686"/>`).join('')}<path d="${area}" fill="url(#${id})" stroke="none"/><path class="chart-line" d="${line}"/>${pts.map(([x,y],i)=>`<circle class="chart-point" cx="${x}" cy="${y}" r="5"><title>${i+1}/10: ${unit==='R$'?money(values[i]):values[i]+' '+unit}</title></circle>`).join('')}<circle cx="${pts.at(-1)[0]}" cy="${pts.at(-1)[1]}" r="3" fill="var(--bg)" stroke="currentColor"/></svg><div class="chart-axis">${labels.map(s=>`<span>${s}</span>`).join('')}</div></div>`;}
function financeChart(){let cumulative=0;const rows=dailyLedger().slice(0,22),values=rows.map(r=>{cumulative+=chartKind==='receitas'?r.incoming:chartKind==='despesas'?r.outgoing:r.net;return cumulative;});return `<section class="panel padding performance-panel"><div class="section-head"><div><h2>O movimento do seu mês</h2><p class="row-meta">Acumulado dos lançamentos finalizados de outubro</p></div><div class="segmented">${[['saldo','Saldo'],['receitas','Entradas'],['despesas','Saídas']].map(([id,name])=>`<button class="${chartKind===id?'active':''}" data-action="chartKind" data-kind="${id}" aria-pressed="${chartKind===id}">${name}</button>`).join('')}</div></div><div class="chart-headline ${chartKind==='despesas'?'rose':'mint'}"><strong>${money(values.at(-1))}</strong><span>${chartKind==='saldo'?'resultado do mês':chartKind==='receitas'?'recebido em outubro':'pago em outubro'}</span></div>${chart(values,{color:chartKind==='despesas'?'rose':'mint',label:'Acumulado financeiro de outubro até o dia 22',labels:['01 out','06 out','11 out','16 out','22 out']})}<div class="chart-foot"><span><i class="legend-dot mint"></i>Entradas ${money(6435)}</span><span><i class="legend-dot rose"></i>Saídas ${money(4355.5)}</span><span>16 lançamentos</span></div></section>`;}
function financeMonthLabel(){return new Date(financeYear,financeMonth,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});}
function calendarControls(){return `<div class="calendar-controls"><div class="month-picker"><button class="icon-button" data-action="monthStep" data-step="-1" aria-label="Mês anterior">‹</button><strong>${financeMonthLabel()}</strong><button class="icon-button" data-action="monthStep" data-step="1" aria-label="Próximo mês">›</button></div><button class="button" data-action="currentMonth">Mês atual</button><label class="weekend-toggle"><input type="checkbox" data-finance-weekends ${financeWeekends?'checked':''}>Mostrar fins de semana</label></div>`;}
function heatmap(kind='finance'){
 const financial=kind==='finance',month=financial?financeMonth:9,year=financial?financeYear:2026,known=month===9&&year===2026,weekends=!financial||financeWeekends,cols=weekends?7:5;
 const first=new Date(year,month,1),offset=(first.getDay()+6)%7,total=new Date(year,month+1,0).getDate(),length=Math.ceil((offset+total)/7)*7,ledger=dailyLedger();
 const cells=Array.from({length},(_,i)=>new Date(year,month,i-offset+1)).filter(d=>weekends||(d.getDay()!==0&&d.getDay()!==6));
 return `<div class="calendar-weekdays" style="grid-template-columns:repeat(${cols},1fr)">${['Seg','Ter','Qua','Qui','Sex',...(weekends?['Sáb','Dom']:[])].map(d=>`<span>${d}</span>`).join('')}</div><div class="month-grid" style="grid-template-columns:repeat(${cols},minmax(0,1fr))">${cells.map(date=>{
 const day=date.getDate();if(date.getMonth()!==month)return `<div class="day-cell outside-month" aria-label="${date.toLocaleDateString('pt-BR')}, fora do mês"><span class="day-number">${day}</span></div>`;
 const r=known?ledger[day-1]:{incoming:0,outgoing:0,net:0},value=financeDayMode==='entradas'?r.incoming:financeDayMode==='saidas'?-r.outgoing:r.net,count=known?(r.count??[...receipts,...expenses].filter(t=>Number(t[3].split('/')[0])===day).length):0;
 const marked=kind==='workout'?state.extra.workoutLog.some(x=>x.day===day):kind==='cave'?state.extra.caveDays.includes(day):false,events=known?calendarEvents(day):[];
 return `<button class="day-cell ${financial&&value>0?'positive':financial&&value<0?'negative':marked?'positive':'empty-day'} ${known&&day===22?'is-today':''}" data-action="${financial?'financeDay':'calendarDay'}" data-day="${day}" data-kind="${kind}" aria-label="${day} de ${financial?financeMonthLabel():'outubro de 2026'}${financial&&known?', '+money(value):''}"><span class="day-number">${day}</span>${financial?`<div class="day-value">${count?`<strong>${value>0?'+':value<0?'−':''}${Math.abs(value)>=1000?(Math.abs(value)/1000).toLocaleString('pt-BR',{maximumFractionDigits:1})+' mil':Math.abs(value).toLocaleString('pt-BR',{maximumFractionDigits:1})}</strong><small>${count} ${count===1?'lançamento':'lançamentos'}</small>`:''}</div>`:marked?`<span class="day-mark">${icon('check')}</span>`:events.length&&kind==='calendar'?`<span class="event-dots">${events.slice(0,3).map(e=>`<i class="${e.kind}"></i>`).join('')}</span>`:''}</button>`;
 }).join('')}</div>${financial&&!known?'<p class="summary-note">Histórico não incluído no Flow para este mês.</p>':''}`;
}
function calendarEvents(day){const arr=[];if(day===22){state.tasks.forEach(t=>arr.push({name:t.title,time:t.time||'Dia todo',kind:'blue'}));}state.extra.events.filter(e=>e.day===day).forEach(e=>arr.push({name:e.name,time:e.time||'Dia todo',kind:'violet'}));receipts.filter(r=>Number(r[3].split('/')[0])===day).forEach(r=>arr.push({name:r[0],time:money(r[1]),kind:'mint'}));expenses.filter(r=>Number(r[3].split('/')[0])===day).forEach(r=>arr.push({name:r[0],time:'− '+money(r[1]),kind:'rose'}));return arr;}
const oldFinance=finance,oldHome=home,oldHabits=habits,oldRoutine=routine,oldTasks=tasks;
function financeTable(type){const list=type==='receitas'?receipts:type==='despesas'?expenses:subscriptions.map(([n,v])=>[n,v,'Mensal','Novembro']);return `<div class="table-shell"><table><thead><tr><th>Descrição</th><th>Categoria</th><th>${type==='assinaturas'?'Plano':'Data'}</th><th class="number">Valor</th><th class="number">Status</th></tr></thead><tbody>${list.map(([name,value,cat,date])=>`<tr><td>${esc(name)}</td><td>${esc(cat)}</td><td>${type==='assinaturas'?'Mensal':date+'/2026'}</td><td class="number ${type==='receitas'?'mint':type==='despesas'?'rose':''}">${type==='receitas'?'+ ':type==='despesas'?'− ':''}${money(value)}</td><td class="number">${statusBadge('success',type==='assinaturas'?'Ativa':type==='receitas'?'Recebido':'Pago')}</td></tr>`).join('')}</tbody></table></div><div class="finance-bottom"><span>${list.length} registros</span><strong>${money(list.reduce((s,r)=>s+r[1],0))}</strong></div>`;}
finance=function(){const section=views.finance;const tabs=tabset('finance',[['geral','Visão geral'],['insights','Insights'],['calendario','Calendário'],['transacoes','Transações'],['mensal','Mensal'],['recorrentes','Recorrentes'],['cartoes','Cartões'],['caixinha','Caixinha'],['contas','Contas'],['categorias','Categorias']]);let content='';if(section==='geral')content=`<div class="finance-metrics">${metric('Recebido',money(6435),'5 receitas de outubro','upRight')}${metric('Pago',money(4355.5),'11 despesas de outubro','downRight')}${metric('Resultado',money(2079.5),'saldo dos lançamentos','wallet')}${metric('Em conta',money(4049),'Meu computador','coins')}</div><div class="finance-v2-grid"><div class="column">${financeChart()}<section class="panel padding"><div class="section-head"><h2>Seus lançamentos</h2><div class="segmented">${[['receitas','Receitas'],['despesas','Despesas'],['assinaturas','Assinaturas']].map(([id,name])=>`<button class="${financeFilter===id?'active':''}" data-action="financeFilter" data-filter="${id}">${name}</button>`).join('')}</div></div>${financeTable(financeFilter)}</section></div><div class="column">${accountPanel()}<section class="panel padding">${sectionHead('Compromissos recorrentes')}<p class="large-value amber">${money(887.9)}</p><p class="row-meta">11 assinaturas ativas por mês</p><div class="compact-subscriptions">${subscriptions.slice(-5).map(([n,v])=>`<div class="list-row"><span class="row-body">${n}</span><span>${money(v)}</span></div>`).join('')}</div><button class="button quiet" data-action="view" data-group="finance" data-view="recorrentes">Ver todas${icon('arrow')}</button></section></div></div>`;
else if(section==='calendario')content=`<section class="panel padding financial-calendar"><div class="section-head"><div><h2>Seu mês, dia a dia</h2><p class="row-meta">Cada dia mostra os movimentos que você registrou.</p></div><div class="segmented">${[['saldo','Saldo'],['entradas','Entradas'],['saidas','Saídas']].map(([id,name])=>`<button data-action="calendarMode" data-mode="${id}" class="${financeDayMode===id?'active':''}">${name}</button>`).join('')}</div></div><div class="calendar-summary">${financeMonth===9&&financeYear===2026?miniStat('Resultado',money(2079.5),'outubro de 2026','mint')+miniStat('Entradas',money(6435),'recebidas','mint')+miniStat('Saídas',money(4355.5),'pagas','rose'):miniStat('Histórico','—','Mês não importado')}</div>${calendarControls()}${heatmap('finance')}<div class="chart-foot"><span><i class="legend-dot mint"></i>Saldo positivo</span><span><i class="legend-dot rose"></i>Saldo negativo</span><span>Clique em um dia para ver detalhes</span></div></section>`;
else if(section==='insights'){const byCat={};expenses.forEach(r=>byCat[r[2]]=(byCat[r[2]]||0)+r[1]);content=`<div class="finance-metrics">${metric('Recebido',money(6435),'no mês','upRight')}${metric('Comprometido','67,7<span>%</span>','das receitas recebidas','wallet')}${metric('Diferença positiva',money(2079.5),'entre entradas e saídas','sparkles')}${metric('Assinaturas',money(887.9),'ativas, por mês','routine')}</div><div class="two-grid">${financeChart()}<section class="panel padding">${sectionHead('Gastos por categoria')}${Object.entries(byCat).map(([name,v])=>`<div class="category-bar"><div><span>${name}</span><strong>${money(v)}</strong></div>${progress(v/4355.5*100)}</div>`).join('')}<p class="summary-note">A diferença entre receitas e despesas não comprova que esse valor foi guardado.</p></section></div>`;}
else if(section==='transacoes')content=`<section class="panel padding"><div class="section-head"><h2>Transações de outubro</h2><span class="tag">Finalizadas</span></div>${financeTable('receitas')}<div class="section-head" style="margin-top:30px"><h2>Despesas</h2></div>${financeTable('despesas')}</section>`;
else if(section==='mensal')content=`<div class="month-card-grid">${['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'].map((m,i)=>`<section class="panel month-card ${i===9?'current-month':''}"><div class="section-head"><h3>${m}</h3><small>2026</small></div>${i===9?`<p class="large-value mint">${money(2079.5)}</p><p class="row-meta">${money(6435)} recebidos</p><p class="row-meta">${money(4355.5)} pagos</p><button class="button quiet" data-action="view" data-group="finance" data-view="calendario">Abrir mês${icon('arrow')}</button>`:'<p class="row-meta">Histórico não incluído no Flow</p>'}</section>`).join('')}</div>`;
else if(section==='recorrentes')content=`<section class="panel padding"><div class="section-head"><h2>Assinaturas ativas</h2><span class="tag amber">${money(887.9)}/mês</span></div>${financeTable('assinaturas')}</section>`;
else if(section==='cartoes')content=`<div class="two-grid"><section class="panel bank-card"><div class="section-head"><span class="bank-wordmark">nu</span><span>${icon('card')}</span></div><p>Seu cartão</p><h2>Nubank</h2><div class="card-bottom"><span>Crédito</span><span>Limite e fatura não importados</span></div></section><section class="panel padding">${sectionHead('Tudo no mesmo lugar')}<p class="insight-note">O cartão cadastrado no seu Flow está aqui. Os lançamentos finalizados continuam na visão de Transações.</p><button class="button" data-action="view" data-group="finance" data-view="transacoes">Ver lançamentos${icon('arrow')}</button></section></div>`;
else if(section==='caixinha')content=`<section class="panel padding savings-panel"><div class="section-head"><div><p class="eyebrow">Sua reserva</p><h2>Turbo</h2></div><span class="module-symbol mint">${icon('wallet')}</span></div><p class="balance-large">${money(state.extra.savings)}</p><p class="summary-note">Saldo da caixinha no Flow</p><div class="dialog-actions"><button class="button primary" data-action="savings" data-sign="1">${icon('plus')}Depositar</button><button class="button" data-action="savings" data-sign="-1">Retirar${icon('arrow')}</button></div></section>`;
else if(section==='contas')content=`<div class="two-grid">${accountPanel()}<section class="panel padding">${sectionHead('Seu patrimônio registrado')}<p class="balance-large mint">${money(4049+state.extra.savings)}</p><p class="summary-note">Conta Meu computador + caixinha Turbo desta prévia.</p></section></div>`;
else content=`<div class="two-grid">${[['Receitas',['Salário','Freelance','Investimentos','Presentes','Outros'] ,'mint'],['Despesas',['Alimentação','Transporte','Moradia','Lazer','Saúde','Assinaturas','Outros','Cartao de Crédito'],'rose']].map(([name,cats,color])=>`<section class="panel padding">${sectionHead(name)}${cats.map(c=>`<div class="list-row"><i class="legend-dot ${color}"></i><span>${c}</span></div>`).join('')}</section>`).join('')}</div>`;return heading('Seu dinheiro, com clareza','Finanças','Outubro de 2026')+tabs+content;};
function accountPanel(){return `<section class="panel padding account-panel"><div class="account-head"><div class="account-icon">nu</div><div><h3>Meu computador</h3><small>Saldo registrado na sua conta</small></div></div><p class="account-balance">${money(4049)}</p><p class="summary-note">Separado do resultado financeiro de outubro.</p><button class="button quiet" data-action="view" data-group="finance" data-view="contas">Ver conta${icon('arrow')}</button></section>`;}
function workouts(){const tabs=tabset('workout',[['fichas','Meus treinos'],['evolucao','Evolução'],['insights','Insights']]);const w=workoutData.find(w=>w.id===selectedWorkout),doneCount=state.extra.workoutLog.length;let content='';if(views.workout==='fichas')content=`<div class="workout-layout"><div class="column"><section class="panel focus-panel workout-focus"><p class="focus-label">${icon('dumbbell')}TREINO ${w.id}</p><h2 class="focus-title">${w.name}</h2><div class="metadata"><span>${w.items.length} exercícios</span><span>12 repetições</span><span>60s de descanso</span></div><div class="focus-bottom"><span class="focus-reward blue">${icon('sparkles')}+30 XP · +3 coins</span><button class="button primary" data-action="workoutStart" data-workout="${w.id}">${icon('play')}Abrir sessão</button></div></section><section class="panel padding">${sectionHead('Sua ficha')}<div class="exercise-list">${w.items.map((name,i)=>`<div class="list-row"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div class="row-body"><h3 class="row-title">${esc(name)}</h3><p class="row-meta">${w.sets[i]} séries · 12 repetições · ${w.id==='A'&&i===0?'30':'60'}s de descanso</p></div><span class="tag blue">${w.sets[i]} × 12</span></div>`).join('')}</div></section></div><div class="column"><section class="panel padding">${sectionHead('Sua sequência')}<div class="training-select">${workoutData.map(t=>`<button class="workout-selector ${t.id===selectedWorkout?'selected':''}" data-action="workoutSelect" data-workout="${t.id}"><span class="workout-letter">${t.id}</span><span><strong>${t.name}</strong><small>${t.items.length} exercícios</small></span>${icon('chevron')}</button>`).join('')}</div></section><section class="panel padding">${sectionHead('Seu ritmo')}<div class="calendar-summary">${miniStat('Esta semana',doneCount,'treinos no Flow','blue')}${miniStat('Histórico',14,'treinos no Flow','blue')}</div><p class="summary-note">Seus registros anteriores foram preservados no Flow. As sessões daqui ficam no demo.</p></section></div></div>`;
else if(views.workout==='evolucao')content=state.extra.measurements.length?`<section class="panel padding">${sectionHead('Seus check-ins')}${state.extra.measurements.map(m=>`<div class="list-row"><span class="row-body">${esc(m.name)}</span><strong>${esc(m.value)} kg</strong></div>`).join('')}</section>`:blank('O próximo registro começa aqui.','Não havia check-ins corporais na tela consultada do seu Flow.','dumbbell',newButton('Novo check-in corporal','measurement'));
else content=`<div class="three-grid">${metric('No Flow','14','treinos históricos','dumbbell')}${metric('Nesta prévia',doneCount,'sessões concluídas','check')}${metric('Fichas','4','na sua sequência','layers')}</div><section class="panel padding" style="margin-top:22px">${sectionHead('Calendário de treinos')}<p class="quiet-caption">Outubro de 2026</p>${heatmap('workout')}</section>`;return heading('Força vem de constância','Treino','Sua sequência A · B · C · D',newButton('Novo check-in','measurement'))+tabs+content;}
function diet(){const done=Object.values(state.extra.meals).filter(v=>v===true).length;let content='';if(views.diet==='registro')content=`<div class="two-grid diet-layout"><div class="column">${mealsData.map(([time,name,items],i)=>`<article class="panel meal-card ${state.extra.meals[i]?'completed':''}"><div class="meal-top">${check('meal',i,!!state.extra.meals[i],name)}<div class="row-body"><p class="row-meta">${time}</p><h3>${name}</h3></div>${statusBadge(state.extra.meals[i]?'success':i===4?'progress':'pending',state.extra.meals[i]?'Concluída':i===4?'Próxima':'Pendente')}<button class="icon-button" data-action="mealOpen" data-id="${i}" aria-label="Ver itens de ${esc(name)}">${icon(state.extra.mealOpen===i?'down':'chevron')}</button></div>${state.extra.mealOpen===i?`<div class="meal-items">${items.map(s=>`<div>${icon('food')}<span>${esc(s)}</span></div>`).join('')}</div>`:''}</article>`).join('')}</div><aside class="column"><section class="panel padding">${sectionHead('Seu dia em refeições')}<div class="daily-ring" style="--p:${done/5*100}%"><div class="ring-value"><strong>${done}/5</strong><small>refeições completas</small></div></div><p class="insight-note center">Um cuidado de cada vez.</p></section><section class="panel padding">${sectionHead('A seguir')}<p class="row-meta">18:30</p><h3 style="margin-top:10px">Janta (Marmita Congelada 2)</h3><p class="summary-note">Seu plano alimentar cadastrado no Flow, sem alterar alimentos ou quantidades.</p></section></aside></div>`;else content=`<div class="three-grid">${metric('Adesão de hoje',Math.round(done/5*100)+'<span>%</span>','refeições registradas','food')}${metric('Planejadas','5','refeições no dia','routine')}${metric('Itens do plano','22','distribuídos nas refeições','layers')}</div><section class="panel padding" style="margin-top:22px">${sectionHead('Equilíbrio por refeição')}${mealsData.map(([time,name],i)=>`<div class="category-bar"><div><span>${name}</span><strong>${state.extra.meals[i]?'Concluída':time}</strong></div>${progress(state.extra.meals[i]?100:0)}</div>`).join('')}<p class="summary-note">A visualização reflete apenas as marcações de hoje. Não foi criado um histórico alimentar fictício.</p></section>`;return heading('Cuidar também é rotina','Dieta','Suas refeições, organizadas para o dia.')+tabset('diet',[['registro','Registro'],['insights','Insights']])+content;}
function calendar(){const events=calendarEvents(selectedCalendarDay);let content;if(views.calendar==='mes')content=`<div class="calendar-layout"><section class="panel padding"><div class="section-head"><h2>Outubro de 2026</h2><button class="button small" data-action="today">Hoje${icon('calendar')}</button></div>${heatmap('calendar')}<div class="chart-foot"><span><i class="legend-dot blue"></i>Tarefas</span><span><i class="legend-dot mint"></i>Entradas</span><span><i class="legend-dot rose"></i>Saídas</span></div></section><aside class="panel padding"><p class="eyebrow">${selectedCalendarDay} de outubro</p><h2>Sua agenda</h2><div style="margin-top:25px">${events.length?events.map(e=>`<div class="list-row"><i class="legend-dot ${e.kind}"></i><div class="row-body"><p class="row-title">${esc(e.name)}</p><p class="row-meta">${esc(e.time)}</p></div></div>`).join(''):'<p class="quiet-caption">Nenhum evento importado para este dia.</p>'}</div><button class="button quiet" data-action="newRecord" data-kind="event">Adicionar evento${icon('plus')}</button></aside></div>`;else if(views.calendar==='dia')content=`<section class="panel padding">${sectionHead('Quinta, 22 de outubro')}<div class="day-timeline">${state.routine.map(r=>`<div class="timeline-row"><span>${r.time}</span><div class="timeline-event amber"><strong>${esc(r.name)}</strong><small>Rotina</small></div></div>`).join('')}${state.tasks.filter(t=>t.time).map(t=>`<div class="timeline-row"><span>${t.time}</span><div class="timeline-event blue"><strong>${esc(t.title)}</strong><small>Tarefa</small></div></div>`).join('')}</div></section>`;else content=`<section class="panel padding">${sectionHead('Agenda de outubro')}${dailyLedger().filter(r=>calendarEvents(r.day).length).map(r=>`<div class="agenda-day"><div class="agenda-date"><strong>${r.day}</strong><span>OUT</span></div><div>${calendarEvents(r.day).map(e=>`<div class="list-row"><i class="legend-dot ${e.kind}"></i><span class="row-body">${esc(e.name)}</span><small>${esc(e.time)}</small></div>`).join('')}</div></div>`).join('')}</section>`;return heading('Espaço para o que importa','Calendário','Rotina, tarefas e compromissos na mesma visão.',newButton('Novo evento','event'))+tabset('calendar',[['mes','Mês'],['dia','Dia'],['agenda','Agenda']])+content;}
function shopping(){const data=state.extra.shopping,tab=views.shopping;let content='';if(tab==='planejadas'||tab==='comprados'){const list=data.filter(s=>tab==='comprados'?s.bought:!s.bought);content=list.length?`<div class="purchase-grid">${list.map(s=>`<article class="panel purchase-card"><div class="section-head"><span class="module-symbol amber">${icon('cart')}</span><span class="tag ${s.priority==='Alta'?'amber':''}">${esc(s.priority)}</span></div><h3>${esc(s.name)}</h3><p class="purchase-price">${money(s.value)}</p>${s.bought&&s.date?`<p class="row-meta" style="margin-bottom:15px">Comprado em ${s.date}</p>`:''}<div class="purchase-bottom"><select data-shopping-status="${s.id}" aria-label="Status de ${esc(s.name)}">${['Só olhando','Quero comprar','Comparando'].map(v=>`<option ${s.status===v?'selected':''}>${v}</option>`).join('')}</select><button class="check ${s.bought?'checked':''}" data-action="purchase" data-id="${s.id}" aria-label="${s.bought?'Reabrir':'Marcar comprado'} ${esc(s.name)}">${icon(s.bought?'check':'plus')}</button></div></article>`).join('')}</div>`:blank('Tudo organizado por aqui.','As compras marcadas no Flow aparecem nesta aba.','cart');}else if(tab==='mercado')content=`<section class="panel padding">${sectionHead('Sua lista de mercado')}${state.extra.market.length?state.extra.market.map((m,i)=>`<div class="list-row">${check('market',i,m.done,m.name)}<span class="row-body">${esc(m.name)}</span><small>${esc(m.value||'')}</small></div>`).join(''):'<p class="quiet-caption">Nenhum item pendente no mercado na consulta ao seu Flow.</p>'}<button class="button" data-action="newRecord" data-kind="market">${icon('plus')}Adicionar item</button></section>`;else content=state.extra.orders.length?`<div class="purchase-grid">${state.extra.orders.map(o=>`<section class="panel padding">${statusBadge('progress','Acompanhando')}<h3 style="margin-top:20px">${esc(o.name)}</h3><p class="row-meta">${esc(o.value||'Pedido registrado no Flow')}</p></section>`).join('')}</div>`:blank('Seus pedidos, acompanhados.','Adicione um pedido para organizar as próximas entregas.','cart',newButton('Novo pedido','order'));if(tab==='comprados'&&state.extra.marketHistory?.length)content+=`<section class="panel padding" style="margin-top:24px">${sectionHead('Mercado · 17 comprados')}${state.extra.marketHistory.map(([name,date])=>`<div class="list-row"><span class="paid">${icon('check')}</span><span class="row-body">${esc(name)}</span><small>${date}</small></div>`).join('')}</section>`;return heading('Comprar com intenção','Lista de compras',`${data.filter(s=>!s.bought).length} itens planejados no Flow.`,newButton('Novo item','shopping'))+tabset('shopping',[['mercado','Mercado'],['planejadas','Planejadas'],['comprados','Comprados'],['pedidos','Pedidos']])+content;}
function zone(){const active=state.tasks.filter(t=>!t.done);let content;if(views.zone==='matriz')content=`<div class="eisenhower-grid">${[['fazer','Fazer agora','Urgente e importante','rose'],['agendar','Agendar','Importante, sem urgência','blue'],['delegar','Delegar','Urgente, menos importante','amber'],['avaliar','Avaliar','Revisar com calma','violet']].map(([id,name,sub,color])=>`<section class="panel quadrant ${color}"><div class="quadrant-heading"><i class="legend-dot ${color}"></i><div><h2>${name}</h2><p>${sub}</p></div><span>${active.filter(t=>(state.extra.quadrants[t.id]||'fazer')===id).length}</span></div>${active.filter(t=>(state.extra.quadrants[t.id]||'fazer')===id).map(t=>`<div class="zone-task"><div class="list-row">${check('task',t.id,t.done,t.title)}<h3 class="row-body">${esc(t.title)}</h3></div><div class="zone-task-bottom"><small>${t.time||'Hoje'}</small><select aria-label="Quadrante de ${esc(t.title)}" data-quadrant="${t.id}">${[['fazer','Fazer agora'],['agendar','Agendar'],['delegar','Delegar'],['avaliar','Avaliar']].map(([k,v])=>`<option value="${k}" ${(state.extra.quadrants[t.id]||'fazer')===k?'selected':''}>${v}</option>`).join('')}</select></div></div>`).join('')||'<p class="quadrant-empty">Espaço para decidir melhor.</p>'}</section>`).join('')}</div>`;else content=`<div class="focus-zone"><section class="panel padding"><p class="eyebrow violet">Uma tarefa de cada vez</p><h2>Entre no seu Flow.</h2><p class="insight-note" style="margin:18px 0 28px">Escolha uma tarefa e reserve um momento só para ela.</p>${active.map(t=>`<div class="list-row"><div class="row-body"><h3>${esc(t.title)}</h3><p class="row-meta">${esc(t.category)}</p></div><button class="button small" data-action="focus" data-id="${t.id}">${icon('play')}Focar</button></div>`).join('')||'<p class="quiet-caption">Todas as suas tarefas estão concluídas.</p>'}</section></div>`;return heading('Escolha o que merece sua atenção','Zone',`${active.length} tarefas ativas. Mais intenção, menos ruído.`)+tabset('zone',[['matriz','Eisenhower'],['foco','Foco']])+content;}
function cave(){const sections=[];return heading('Um compromisso com você','Modo Caverna','Seu plano cadastrado: 01/03/2026 a 29/04/2026.',`<button class="button primary" data-action="caveDay">${icon('check')}${state.extra.caveDays.includes(flowToday())?'Dia marcado no Flow':'Marcar dia completo'}</button>`)+`<section class="panel cave-banner"><span class="module-symbol amber">${icon('mountain')}</span><div><h2>Disciplina com propósito.</h2><p>O período original terminou. Seus objetivos continuam aqui.</p></div>${statusBadge('expired','Ciclo encerrado')}</section><div class="cave-layout"><div class="two-grid">${sections.map(([name,items,ico],s)=>`<section class="panel padding">${sectionHead(name,'','',ico)}${items.map((item,i)=>{const key=s+'-'+i,done=state.extra.cave.includes(key);return `<div class="list-row">${check('caveItem',key,done,item)}<span class="row-body ${done?'muted':''}">${esc(item)}</span></div>`;}).join('')}</section>`).join('')}</div><section class="panel padding">${sectionHead('Seu compromisso de hoje')}<p class="large-value amber">${state.extra.cave.length}<span> / 15</span></p><p class="row-meta">itens marcados no Flow</p><div style="margin:25px 0">${progress(state.extra.cave.length/15*100)}</div><p class="summary-note">Dias decorridos e dias cumpridos são medidas diferentes. Aqui, progresso depende das suas marcações.</p></section></div>`;}
function shop(){const content=views.shop==='recompensas'?`<div class="reward-grid">${rewardData.map(([name,cost,category,streak,ico],id)=>`<article class="panel reward-card"><div class="section-head"><span class="module-symbol violet">${icon(ico)}</span><span class="tag">${category}</span></div><h3>${name}</h3><p class="reward-cost">${icon('coins')}<strong>${cost}</strong><span>coins</span></p><div class="reward-bottom"><small>${streak?`${streak} dias de consistência`:'Disponível no seu ritmo'}</small><button class="button small ${streak?'':'primary'}" data-action="redeem" data-id="${id}" ${streak>1?'disabled':''}>${streak>1?icon('clock'):'Trocar'}</button></div></article>`).join('')}</div>`:state.extra.redeemed.length?`<section class="panel padding">${sectionHead('Recompensas da prévia')}${state.extra.redeemed.map(r=>`<div class="list-row"><span class="module-symbol violet">${icon('gift')}</span><div class="row-body"><h3>${esc(r.name)}</h3><p class="row-meta">22 de outubro · resgate local</p></div><span class="amber">−${r.cost} coins</span></div>`).join('')}</section>`:blank('Seu esforço também merece pausa.','As recompensas trocadas no Flow vão aparecer aqui.','gift');return heading('Celebre o caminho','Loja',`${state.coins} coins disponíveis na sua prévia.`)+tabset('shop',[['recompensas','Recompensas'],['historico','Histórico']])+content;}
function goals(){const items=state.extra.goals.filter(g=>g.status===views.goals);return heading('Direção para os próximos passos','Metas','O importante é saber para onde você está indo.',newButton('Nova meta','goal'))+tabset('goals',[['ativas','Ativas'],['concluidas','Concluídas'],['pausadas','Pausadas']])+(items.length?`<div class="goal-grid">${items.map(g=>`<section class="panel goal-card"><div class="section-head"><span class="module-symbol mint">${icon('flag')}</span><span class="tag">${esc(g.category)}</span></div><h2>${esc(g.name)}</h2><div class="goal-status">${statusBadge(g.status==='concluidas'?'success':g.status==='pausadas'?'paused':'progress',g.status==='concluidas'?'Concluída':g.status==='pausadas'?'Pausada':'Em andamento')}</div><div class="goal-value"><strong>${g.progress}<span>%</span></strong><span class="mint">+100 XP</span></div>${progress(g.progress)}<p class="summary-note">Prazo cadastrado: ${esc(g.deadline)}</p><div class="goal-controls"><label>Progresso<input type="range" min="0" max="100" value="${g.progress}" data-goal-progress="${g.id}" aria-label="Progresso de ${esc(g.name)}"></label><select data-goal-status="${g.id}" aria-label="Status de ${esc(g.name)}">${[['ativas','Ativa'],['pausadas','Pausada'],['concluidas','Concluída']].map(([id,title])=>`<option value="${id}" ${g.status===id?'selected':''}>${title}</option>`).join('')}</select></div></section>`).join('')}</div>`:blank('Há espaço para o próximo objetivo.','Nenhuma meta desta prévia nesta situação.','flag'));}
function settings(){return heading('Do seu jeito','Configurações','A mesma linguagem visual, em cada parte do Flow.')+`<div class="settings-layout"><section class="panel padding"><div class="profile-heading"><div class="profile-avatar">VD</div><div><h2>Meu computador</h2><p class="row-meta">Meu computador · Nível 9</p></div><span class="tag mint">${state.xp.toLocaleString('pt-BR')} XP</span></div><div class="settings-section"><h3>Aparência</h3><p class="summary-note">Dark profundo, vidro suave e cores por contexto.</p><button class="button" data-action="preferences">${icon('sliders')}Personalizar aparência</button></div><div class="settings-section"><h3>Preferências</h3>${[['sounds','Sons de navegação','Feedback ao interagir'],['hover','Barra no hover','Nomes dos módulos ao passar o mouse'],['reminders','Lembretes','Preferência local para a prévia']].map(([id,title,sub])=>`<label class="setting-row"><span><strong>${title}</strong><small>${sub}</small></span><input type="checkbox" role="switch" data-setting="${id}" ${state.extra.settings[id]?'checked':''}></label>`).join('')}</div><div class="settings-section"><h3>Seus dados</h3><p class="summary-note">Seus dados são salvos automaticamente neste computador, no seu perfil do Windows, com cópia diária de recuperação.</p><button class="button" data-action="exportDemo">${icon('download')}Exportar dados da prévia</button></div></section><aside class="column"><section class="panel padding">${sectionHead('Uma identidade, várias áreas')}<div class="design-swatches">${[['mint','Progresso e finanças'],['blue','Tarefas e treino'],['amber','Rotina e planejamento'],['violet','Foco e recompensas'],['rose','Saídas e alertas']].map(([color,name])=>`<div class="list-row"><i class="legend-dot ${color}"></i><span>${name}</span></div>`).join('')}</div></section><section class="panel padding"><p class="eyebrow">Flow, prévia 02</p><h3>Mais escuro. Mais seu.</h3><p class="summary-note">14 módulos na mesma base visual. Seus dados pessoais ficam neste computador.</p></section></aside></div>`;}
function checkins(){const entries=state.extra.wellbeing;return `<section class="panel padding wellbeing-panel">${sectionHead('Como está seu dia?')}<form id="wellbeing-form"><div class="three-grid">${[['sleep','Sono (horas)',7,0,12],['productivity','Produtividade',7,0,10],['mood','Humor',7,0,10]].map(([id,label,v,min,max])=>`<label class="field">${label}<output id="output-${id}">${v}</output><input type="range" name="${id}" min="${min}" max="${max}" value="${v}" data-output="output-${id}"></label>`).join('')}</div><button class="button primary" type="submit">Salvar check-in</button></form></section>${entries.length?`<section class="panel padding" style="margin-top:22px">${sectionHead('Registros da prévia')}${entries.map(x=>`<div class="list-row"><span class="row-body">22/10 · Sono ${x.sleep}h</span><span>Produtividade ${x.productivity}/10 · Humor ${x.mood}/10</span></div>`).join('')}</section>`:''}`;}
function monthConsistency(kind){const rows=kind==='habits'?state.habits:state.routine;return `<section class="panel padding">${sectionHead('Outubro de 2026')}<p class="quiet-caption">Suas marcações de hoje, sem preencher os dias anteriores com dados fictícios.</p><div class="consistency-scroll"><table class="consistency-table"><thead><tr><th>${kind==='habits'?'Hábito':'Rotina'}</th>${Array.from({length:31},(_,i)=>`<th class="${i===21?'current-day':''}">${i+1}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td>${Array.from({length:31},(_,i)=>`<td><span class="consistency-mark ${i===21?(r.done?'is-done':'is-pending'):'no-data'}" title="${i+1}/10: ${i===21?(r.done?'Concluído':'Pendente hoje'):'Sem histórico importado'}">${i===21&&r.done?icon('check'):''}</span></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="chart-foot"><span><i class="legend-dot mint"></i>Concluído</span><span>Pendente hoje</span><span>Demais dias: sem histórico importado</span></div></section>`;}
function consistency(kind){const entries=kind==='habits'?state.habits:state.routine,done=entries.filter(x=>x.done).length;return `<div class="three-grid">${metric('Hoje',done+'<span> / '+entries.length+'</span>','itens completos','check')}${metric('Adesão',Math.round(done/entries.length*100)+'<span>%</span>','das atividades de hoje','target')}${metric('Ativos',entries.length,'na sua prévia','layers')}</div><section class="panel padding" style="margin-top:22px">${sectionHead('Hoje, item por item')}${entries.map(x=>`<div class="list-row"><span class="row-body">${esc(x.name)}</span><span class="${x.done?'mint':'muted'}">${x.done?'Concluído':'Pendente'}</span></div>`).join('')}<p class="summary-note">Os indicadores usam suas marcações locais. O histórico dos meses anteriores não foi importado.</p></section>`;}
habits=function(){let body=oldHabits();const at=body.indexOf('<div class="habit-page-grid">');return body.slice(0,at)+tabset('habits',[['hoje','Hoje'],['mensal','Mensal'],['geral','Geral']])+(views.habits==='hoje'?body.slice(at):views.habits==='mensal'?monthConsistency('habits'):consistency('habits'));};
routine=function(){let body=oldRoutine();const at=body.indexOf('<div class="routine-page">');return body.slice(0,at)+tabset('routine',[['cronograma','Cronograma'],['bemestar','Bem-estar'],['consistencia','Consistência']])+(views.routine==='cronograma'?body.slice(at):views.routine==='bemestar'?checkins():monthConsistency('routine'));};
tasks=function(){let body=oldTasks();const toolbarStart=body.indexOf('<div class="toolbar">'),layoutStart=body.indexOf('<div class="tasks-layout">');const items=state.tasks.filter(t=>views.tasks==='concluidas'?t.done:views.tasks==='algumdia'||views.tasks==='atrasadas'?false:!t.done);return body.slice(0,toolbarStart)+tabset('tasks',[['hoje','Hoje'],['semana','Semana'],['mes','Mês'],['atrasadas','Atrasadas'],['concluidas','Concluídas'],['algumdia','Algum dia']])+`<div class="tasks-layout"><div>${items.length?items.map(taskCard).join(''):blank(views.tasks==='concluidas'?'Suas conclusões ficam aqui.':'Nenhuma tarefa desta cópia nesta aba.','Você pode criar novas tarefas sem alterar o Flow.','tasks',newButton('Nova tarefa','taskExtra'))}</div><aside class="panel side-note">${sectionHead('Sua rotina','Abrir','rotina')}${state.routine.filter(r=>r.period==='noite').map(r=>`<div class="list-row"><span class="time-label">${r.time}</span><span class="row-body">${esc(r.name)}</span></div>`).join('')}</aside></div>`;};
home=function(){return oldHome()+`<section class="module-overview"><div class="section-head"><h2>Seu Flow, por inteiro</h2><small>14 áreas, uma só direção</small></div><div class="module-grid">${nav.filter(n=>!['inicio','configuracoes'].includes(n[0])).map(([id,title,ico])=>`<a class="panel module-link ${pageColors[id]}" href="#${id}"><span class="module-symbol ${pageColors[id]}">${icon(ico)}</span><span>${title}</span>${icon('arrow')}</a>`).join('')}</div></section>`;};
function renderV2(){ensureExtra();if(!nav.some(n=>n[0]===page))page='inicio';document.documentElement.dataset.area=pageColors[page];$('#breadcrumb').textContent=nav.find(n=>n[0]===page)[1];$('#navigation').innerHTML=nav.map(([id,title,ico])=>`<a class="dock-item ${id===page?'active':''} ${['inicio','tarefas','habitos','financas'].includes(id)?'mobile-primary':'mobile-secondary'}" href="#${id}" ${id===page?'aria-current="page"':''} aria-label="${title}">${icon(ico)}<span class="nav-label">${title}</span></a>`).join('')+`<button class="dock-item mobile-more" data-action="allModules" aria-label="Mais módulos">${icon('more')}<span class="nav-label">Mais</span></button>`;$('#content').innerHTML=({inicio:home,tarefas:tasks,habitos:habits,rotina:routine,financas:finance,treino:workouts,dieta:diet,calendario:calendar,compras:shopping,zone,caverna:cave,loja:shop,metas:goals,configuracoes:settings})[page]();updateStats();}
render=renderV2;
function newRecord(kind){const config={shopping:['Novo item planejado','Nome do item','Valor estimado (R$)'],market:['Adicionar ao mercado','O que comprar?','Quantidade'],order:['Novo pedido','Nome do pedido','Acompanhamento'],goal:['Nova meta','O que você quer conquistar?','Prazo'],event:['Novo evento','Nome do evento','Horário'],measurement:['Check-in corporal','Identificação do registro','Peso (kg)'],taskExtra:['Nova tarefa','Título','Horário']};const [title,label,second]=config[kind]||config.shopping;modal(dialogHead(title)+`<form id="extra-form" data-kind="${kind}"><label class="field">${label}<input name="name" required maxlength="120" autocomplete="off"></label><label class="field">${second}<input name="value" ${['shopping','measurement'].includes(kind)?'type="number" min="0" step="0.01"':kind==='event'||kind==='taskExtra'?'type="time"':'type="text"'} ${kind==='measurement'?'required':''}></label>${kind==='event'?'<label class="field">Dia de outubro<input name="day" type="number" min="1" max="31" value="22" required></label>':''}<p class="settings-note">Salvo somente no Flow local.</p><div class="dialog-actions"><button class="button" type="button" data-action="close">Cancelar</button><button class="button primary" type="submit">Salvar</button></div></form>`);}
function showFinanceDay(day){const known=financeMonth===9&&financeYear===2026,ins=known?receipts.filter(r=>Number(r[3].split('/')[0])===day):[],outs=known?expenses.filter(r=>Number(r[3].split('/')[0])===day):[];modal(dialogHead(day+' de '+financeMonthLabel())+(ins.length||outs.length?ins.map(r=>`<div class="list-row"><span class="row-body">${esc(r[0])}</span><strong class="mint">+${money(r[1])}</strong></div>`).join('')+outs.map(r=>`<div class="list-row"><span class="row-body">${esc(r[0])}</span><strong class="rose">−${money(r[1])}</strong></div>`).join(''):'<p class="insight-note">Nenhum lançamento importado para este dia.</p>'));}
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;ensureExtra();const action=b.dataset.action,id=Number(b.dataset.id);
if(action==='view'){views[b.dataset.group]=b.dataset.view;if(b.dataset.group==='tasks')taskFilter=b.dataset.view;render();}
else if(action==='allModules')modal(dialogHead('Todo o seu Flow')+`<div class="all-modules">${nav.map(([id,title,ico])=>`<a class="module-link ${pageColors[id]}" data-action="close" href="#${id}"><span class="module-symbol ${pageColors[id]}">${icon(ico)}</span><span>${title}</span>${icon('chevron')}</a>`).join('')}</div>`);
else if(action==='chartKind'){chartKind=b.dataset.kind;render();}
else if(action==='calendarMode'){financeDayMode=b.dataset.mode;render();}
else if(action==='financeDay')showFinanceDay(Number(b.dataset.day));
else if(action==='calendarDay'){selectedCalendarDay=Number(b.dataset.day);if(b.dataset.kind==='calendar')render();else toast(b.dataset.kind==='workout'?'As sessões concluídas no Flow são marcadas aqui.':'Seu registro local de compromisso.');}
else if(action==='today'){selectedCalendarDay=22;render();}
else if(action==='workoutSelect'){selectedWorkout=b.dataset.workout;render();}
else if(action==='workoutStart'){const w=workoutData.find(w=>w.id===b.dataset.workout);modal(dialogHead('Treino '+w.id+' · '+w.name)+`<div>${w.items.map((n,i)=>`<div class="list-row">${check('exercise',i,!!state.extra.exercises[w.id+'-'+i],n,`data-workout="${w.id}"`)}<span class="row-body">${esc(n)}</span><small>${w.sets[i]} × 12</small></div>`).join('')}</div><div class="dialog-actions"><button class="button primary" data-action="finishWorkout" data-workout="${w.id}">Concluir sessão no Flow${icon('check')}</button></div>`);}
else if(action==='exercise'){const key=b.dataset.workout+'-'+id;state.extra.exercises[key]=!state.extra.exercises[key];b.classList.toggle('checked',state.extra.exercises[key]);b.innerHTML=state.extra.exercises[key]?icon('check'):'';b.setAttribute('aria-pressed',String(state.extra.exercises[key]));save();}
else if(action==='finishWorkout'){if(!state.extra.workoutLog.some(w=>w.day===flowToday()&&w.workout===b.dataset.workout)){state.extra.workoutLog.push({day:flowToday(),date:flowToday(),workout:b.dataset.workout});state.xp+=30;state.coins+=3;save();}$('#modal').close();render();toast('Sessão registrada somente no Flow.');}
else if(action==='meal'){state.extra.meals[id]=!state.extra.meals[id];save();render();}
else if(action==='mealOpen'){state.extra.mealOpen=state.extra.mealOpen===id?-1:id;save();render();}
else if(action==='newRecord')newRecord(b.dataset.kind);
else if(action==='market'){state.extra.market[id].done=!state.extra.market[id].done;save();render();}
else if(action==='purchase'){const s=state.extra.shopping.find(s=>s.id===id);s.bought=!s.bought;save();render();toast(s.bought?'Marcado como comprado no Flow.':'Item devolvido ao planejamento.');}
else if(action==='caveItem'){const key=b.dataset.id,pos=state.extra.cave.indexOf(key);if(pos<0)state.extra.cave.push(key);else state.extra.cave.splice(pos,1);save();render();}
else if(action==='caveDay'){const pos=state.extra.caveDays.indexOf(flowToday());if(pos<0)state.extra.caveDays.push(flowToday());else state.extra.caveDays.splice(pos,1);save();render();toast('Registro de hoje atualizado no Flow.');}
else if(action==='redeem'){const [name,cost]=rewardData[id];if(state.coins<cost){toast('Coins insuficientes no Flow.');return;}modal(dialogHead('Uma pausa merecida')+`<h3>${name}</h3><p class="insight-note" style="margin-top:15px">Trocar ${cost} coins no Flow?</p><div class="dialog-actions"><button class="button" data-action="close">Agora não</button><button class="button primary" data-action="confirmRedeem" data-id="${id}">Trocar ${cost} coins</button></div>`);}
else if(action==='confirmRedeem'){const [name,cost]=rewardData[id];if(state.coins>=cost){state.coins-=cost;state.extra.redeemed.push({name,cost});save();$('#modal').close();render();toast('Recompensa trocada apenas no Flow.');}}
else if(action==='savings'){modal(dialogHead(Number(b.dataset.sign)>0?'Depositar na Turbo':'Retirar da Turbo')+`<form id="savings-form" data-sign="${b.dataset.sign}"><label class="field">Valor (R$)<input name="amount" type="number" min="0.01" step="0.01" required></label><p class="settings-note">Simulação local. Não movimenta dinheiro nem altera o saldo do Flow.</p><div class="dialog-actions"><button class="button primary">Confirmar no Flow</button></div></form>`);}
else if(action==='exportDemo'){const blob=new Blob([JSON.stringify({demo:true,snapshot:flowToday(),state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='flow-previa-local.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
document.addEventListener('submit',event=>{const f=event.target;if(f.id==='task-form'){views.tasks='hoje';render();}else if(f.id==='extra-form'){event.preventDefault();const data=new FormData(f),name=String(data.get('name')||'').trim(),value=String(data.get('value')||''),id=Date.now();if(!name)return;const kind=f.dataset.kind;if(kind==='shopping')state.extra.shopping.push({id,name,value:Number(value)||0,priority:'Média',status:'Só olhando',bought:false});if(kind==='market')state.extra.market.push({name,value,done:false});if(kind==='order')state.extra.orders.push({name,value});if(kind==='goal')state.extra.goals.push({id,name,progress:0,status:'ativas',category:'Pessoal',deadline:value||'Sem prazo'});if(kind==='event')state.extra.events.push({name,time:value,day:Number(data.get('day'))});if(kind==='measurement')state.extra.measurements.push({name,value:Number(value)});if(kind==='taskExtra')state.tasks.push({id,title:name,category:'Pessoal',time:value,subs:[],done:false,open:false});save();$('#modal').close();render();toast('Salvo somente no Flow.');}else if(f.id==='wellbeing-form'){event.preventDefault();const data=new FormData(f);state.extra.wellbeing.push({sleep:Number(data.get('sleep')),productivity:Number(data.get('productivity')),mood:Number(data.get('mood'))});save();render();toast('Check-in registrado no Flow.');}else if(f.id==='savings-form'){event.preventDefault();const amount=Number(new FormData(f).get('amount')),sign=Number(f.dataset.sign);if(amount>0&&state.extra.savings+sign*amount>=0){state.extra.savings+=sign*amount;save();$('#modal').close();render();toast('Saldo simulado atualizado.');}else toast('Confira o valor e o saldo da caixinha.');}});
document.addEventListener('change',event=>{const e=event.target;if(e.matches('[data-shopping-status]')){state.extra.shopping.find(s=>s.id===Number(e.dataset.shoppingStatus)).status=e.value;save();}if(e.matches('[data-quadrant]')){state.extra.quadrants[e.dataset.quadrant]=e.value;save();render();}if(e.matches('[data-goal-progress]')){const g=state.extra.goals.find(g=>g.id===Number(e.dataset.goalProgress));g.progress=Number(e.value);if(g.progress===100)g.status='concluidas';save();render();}if(e.matches('[data-goal-status]')){state.extra.goals.find(g=>g.id===Number(e.dataset.goalStatus)).status=e.value;save();render();}if(e.matches('[data-setting]')){state.extra.settings[e.dataset.setting]=e.checked;save();}});
document.addEventListener('input',event=>{if(event.target.dataset.output)document.getElementById(event.target.dataset.output).textContent=event.target.value;});
page=location.hash.slice(1)||'inicio';ensureExtra();render();

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b?.dataset.action==='monthStep'){const d=new Date(financeYear,financeMonth+Number(b.dataset.step),1);financeMonth=d.getMonth();financeYear=d.getFullYear();render();}if(b?.dataset.action==='currentMonth'){financeMonth=9;financeYear=2026;render();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-finance-weekends]')){financeWeekends=e.target.checked;render();}});


